    def test_real_multiline_edit_saves_lf_and_leaves_other_fields_untouched(self):
        survey_id, saved = self.seed()
        self.open_edit_direct(survey_id)

        # 只改两处多行文字：第 1 题题目标题重排为三行，第 2 题第 2 个选项改写。
        new_q0 = "必填文本题\n新第二行\n新增第三行"
